  'about.bookshopLeadIn': "የመጽሐፍ መደብራችንን በሚያስተዳድረው በተመሳሳይ አነስተኛ ንግድ የተሰራ:",
  "about.eyebrow": "ስለ Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — ስለ እኛ",
  "about.founderHeading": "📖 ስለ መስራቹ",
  "about.founder.p1": "ሰላም፣ እኔ ኮንሴፕሲዮን ነኝ፣ የLuminous StockHaven መስራች።",
  "about.founder.p2": "እኔ ከትልቅ የቴክኖሎጂ ኩባንያ የመጣሁ አይደለሁም፣ በኮርፖሬት ቢሮ ውስጥም አልቀመጥም። እኔ ልክ እንደ እርስዎ ትንሽ የችርቻሮ ባለቤት ነኝ። ለመጽሐፍት እና ለመጽሐፍ ወዳጆች በእጅ ለተሠሩ ዕቃዎች የሚያተኩሩ አምስት የኢ-ኮሜርስ ሱቆችን እመራለሁ።\nእንደ ብዙ ነጻ ቸርቻሪዎች፣ በብዙ ቦታዎች ላይ ክምችትን ለማስተዳደር፣ የአሳታሚዎችን ISBN ከራሴ በእጅ ከተሠሩ SKUዎች ጋር ለመከታተል እና የአቅራቢ ትዕዛዞችን በአስቸጋሪ የተንታኝ ሉሆች ለማስተናገድ ስሞክር ወደ ስብራት ነጥብ ደረስሁ። የሚረዳኝ መተግበሪያ ስፈልግ ስድስት የተለያዩ አማራጮችን ሞከርሁ። እያንዳንዳቸው ሙሉ በሙሉ ያልተሟሉ፣ በሚያስደንቅ ሁኔታ የሚያደናግሩ ወይም አሳዳጆች ነበሩ — ለመሠረታዊ መሣሪያዎች በወር በመቶዎች የሚቆጠሩ ዶላሮችን ያስከፍሉ ነበር።",
  "about.founder.p3": "ነጻ ፈጣሪዎችን በሚበዘብዝ ኢንዱስትሪ ተበሳጭቼ የራሴን መፍትሔ ለመገንባት ወሰንሁ። Luminous StockHavenን ከአስፈላጊነት ገንብቼአለሁ፣ የራሴን ንግዶች በንጽህና፣ በብቃት እና ሙሉ በሙሉ በአእምሮ ሰላም ለማስኬድ።",
  "about.founder.p4": "እያንዳንዱ ትንሽ የንግድ ባለቤት ገቢውን አደጋ ላይ ሳያደርግ በእውነት የሚሠሩ መሣሪያዎች ይገባዋልና ይህን መድረክ በሐቀኛ እና ተመጣጣኝ ዋጋ ለሕዝብ ለመክፈት ወሰንሁ። እኛ ራሳችንን የምንገዛ ነን፣ ማህበረሰባችንን በጽኑ እንጠብቃለን፣ እና በቸርቻሪ ለቸርቻሪዎች ተገንብተናል።",
  "notice.ariaLabel": "የንግድ ምልክት እና የቅጂ መብት ማስታወቂያ",
  "notice.heading": "🛡️ ለቸርቻሪዎች የተገነባ፣ ለኮርፖሬት አሞሮች ዋጋ የሌለው",
  "notice.intro": "ይህን መተግበሪያ የገነባሁት 5 ሱቆችን ስለማስኬድ እና በመቶዎች ዶላር በሚያደናግር ሶፍትዌር ስለተታለልሁ ደክሞኛል። ይህ መተግበሪያ ነጻ አርቲስቶችን፣ እደ ጥበበኞችን፣ የመጽሐፍ ሻጮችን እና የአካባቢ ሱቆችን ለመጠበቅ ተገንብቷል።",
  "notice.legalHeading": "ለተፎካካሪዎች እና ለአስመስሎዎች የሕግ ማስታወቂያ:",
  "notice.legalBody": "ገበያውን በንቃት እንከታተላለን። መድረካችንን ለመቧጨር፣ የባለቤትነት የሥራ ፍሰቶቻችንን ለመቅዳት ወይም የአእምሯዊ ንብረታችንን ለመጣስ የሚደረግ ማንኛውም ሙከራ ፈጣን እና ኃይለኛ የሕግ እርምጃ ያጋጥመዋል።",
  "notice.acquisitionHeading": "ለግዢ ኩባንያዎች እና ለደላሎች:",
  "notice.acquisitionBody": "ኢሜይል አትላኩልኝ። መልእክት አትላኩልኝ። 'ስትራቴጂካዊ መውጫ' አታቅርቡልኝ። በሺዎች፣ በሚሊዮኖች፣ በቢሊዮኖች ወይም በትሪሊዮኖች ማቅረብ ትችላላችሁ — መልሱ አይደለም ነው። ለቸርቻሪ ባልደረቦቼ ዋጋ ለመጨመር ብቻ ይህን መተግበሪያ አትገዙም። እያንዳንዱ ያልተጠየቀ የግዢ ኢሜይል ወዲያውኑ እንደ ስፓም ምልክት ይደረግበታል፣ እና ጎራችሁ ከመድረካችን በቋሚነት ይታገዳል። ጥረትዎን ይቆጥቡ።",
  "footer.trademarkLine": "ያልተፈቀደ ቅጂ፣ መቅዳት ወይም መቧጨር በጥብቅ የተከለከለ ነው።",
