  "upgrade.pastDueBody": "የመጨረሻ ክፍያዎ አልተሳካም፣ ስለዚህ ይህ ምዝገባ ጊዜው አልፏል። ክፍያው ከተቋረጠበት ቀን ጀምሮ እስኪያስተካክሉት ድረስ ለ14 ቀናት ሙሉ አጠቃቀም ይቀጥልልዎታል። ካልተስተካከለ፣ ምዝገባው ይሰረዛል፣ የስራ ቦታው ለ15 ቀናት ለመመልከት ብቻ ይሆናል፣ ከዚያም መለያው እና መረጃው ሁሉ ይሰረዛል። ከመሰረዙ በፊት በማንኛውም ጊዜ መክፈል ሁሉንም ነገር ይመልሳል። ከታች የክፍያ ዘዴዎን ያዘምኑ። እርዳታ ካስፈለገዎት፣ ኢሜይል ያድርጉ ወደ",
