  "settings.details.address": "አድራሻ",
  'settings.details.taxRate': 'የእኔ የግብር ተመን',
  'settings.details.taxRateHint': 'አንድ ጊዜ አዋቅሩት። እያንዳንዱ አዲስ የሽያጭ ትዕዛዝ ግብሩን ከዚህ ተመን ይሞላል — በአንድ ትዕዛዝ ላይ ግን ግብሩን አሁንም መቀየር ይችላሉ።',
