  "settings.details.taxModeAutomatic": "ራስ-ሰር — በደንበኛው ግዛት መሰረት",
  "settings.details.taxModeHint": "ቋሚ ሁነታ በእያንዳንዱ አዲስ ትዕዛዝ ላይ የእርስዎን ተመን ይጠቀማል። ራስ-ሰር ሁነታ ግዛቱ በትዕዛዙ ላይ እንደገባ የአዲስ ትዕዛዝ ግብር በደንበኛው የግዛት መሰረታዊ ተመን ይሞላል፣ ግዛቱ ከተቀየረም እንደገና ይሞላል። እነዚህ የግዛት መሰረታዊ ተመኖች ናቸው — የአካባቢ ግብሮች ተጨማሪ ሊጨምሩ ይችላሉ። ግዛት የሌለው፣ ወይም ከአሜሪካ ውጭ ያለ ትዕዛዝ ከላይ ያለውን ቋሚ ተመንዎን ይጠቀማል።",
  'settings.details.gs1Prefix': "የGS1 ኩባንያ ቅድመ-ቁጥር",
  'settings.details.gs1PrefixHint': "ከGS1 የቅድመ-ቁጥር ፈቃድ ካለዎት ብቻ። አንዴ ያዘጋጁት፣ የምርት ቅጽ ኮድ አመንጪ ከራስዎ ቁጥሮች እውነተኛ የችርቻሮ UPC እና EAN ኮዶችን መፍጠር ይችላል — እያንዳንዱ አንድ ጊዜ ብቻ ይጠቅማል፣ እንደገና ፈጽሞ አይጠቅምም። ከሌለዎት ባዶ ይተዉት፤ መተግበሪያው ቅድመ-ቁጥር ፈጽሞ አይፈጥርም።",
  'settings.details.gs1LearnMore': "ለGS1 አዲስ ነዎት? በራስዎ ሀገር የሚኖሩ ከሆነ፣ የበለጠ ለማወቅ የዚያ ሀገር አገናኝ ይጠቀሙ፤ በዩናይትድ ስቴትስ የሚኖሩ ከሆነ፣ የGS1 US አገናኝ ይጠቀሙ።",
  'settings.details.gs1LearnMoreUs': "ለGS1 አዲስ ነዎት? በዩናይትድ ስቴትስ የሚኖሩ ከሆነ፣ የበለጠ ለማወቅ የGS1 US አገናኝ ይጠቀሙ።",
