  "settings.security.changeEmailDesc": "መለያዎን ወደ አዲስ ኢሜይል ያዛውሩ። መደብርዎ፣ ክምችትዎ፣ ቡድንዎ እና ታሪክዎ ከሱ ጋር ይንቀሳቀሳሉ — እና አዲስ ነጻ ሙከራ አይጀምርም። ሌላ እያንዳንዱ ገብቶ ያለ መሣሪያ ይወጣል።",
