  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "የShopify POS ሽያጮች የShopify ትዕዛዞች ናቸው። ይህን መደብር ያገናኙ እና እያንዳንዱ ትዕዛዝ እቃዎቹን በራሱ እዚህ ከክምችት ያወጣል።",
  "pos.shopify.tokenNote": "ቶከኑ የሚመጣው በShopify አስተዳዳሪዎ ውስጥ ካለ ብጁ መተግበሪያ ነው። በአገልጋዩ ላይ ብቻ ይቀመጣል እና መቼም ተመልሶ አይታይም።",
