  "crossStore.transferTitle": "ዕቃ ወደ ሌላ ሱቅ ማንቀሳቀስ",
  "crossStore.transferToFirstLocation": "የመጀመሪያው ቦታው",
  "crossStore.transferToLocation": "መድረሻ ቦታ",
  "training.lessons.owner-move-stock.step1": "ጥያቄዎች ለመጠየቅ ናቸው፤ ማንቀሳቀስ የባለቤቱ ሥራ ነው። በሱቆች መካከል የገቢ ሳጥን ገጽ ላይ፣ «ዕቃ አንቅስቅስ» ፓነል እርስዎ — ባለቤቱ — ዕቃን ከዚህ ሱቅ ወደ ሌላ የራስዎ ሱቅ በቀጥታ፣ ያለ ጥያቄ እና ያለ መጠበቅ እንዲልኩ ይፈቅዳል።",
  "training.lessons.owner-move-stock.step2": "ምርቱን፣ የሚነሳበትን ቦታ እና ብዛቱን ይምረጡ። መተግበሪያው በዚያ ቦታ ስንት እንዳለ ያሳያል፣ እና ማንቀሳቀስ ከዚያ በላይ መውሰድ አይችልም።",
  "training.lessons.owner-move-stock.step3": "የሚደርስበትን ሱቅ ይምረጡ፣ እና ከፈለጉ እዚያ ያለውን ትክክለኛ ቦታም። ያ ሱቅ ቀድሞውኑ ተመሳሳዩን SKU ካለው፣ ዕቃው ወደ ያ ምርት ይጨመራል፤ ካልሆነ ምርቱ ከዕቃው ጋር ይገለበጣል።",
  "training.lessons.owner-move-stock.step4": "ሁለቱም ሱቆች መዝገብ ይይዛሉ: ይህ ሱቅ ወደ ውጭ የተላለፈ ማስተላለፍ ያሳያል፣ ሌላኛው ደግሞ መቀበል ያሳያል። ማንቀሳቀስ ካልተቻለ — በቂ ካልኖረ፣ ወይም ሌላኛው ሱቅ የርስዎ ካልሆነ — ምንም ነገር አይንቀሳቀስም እና መተግበሪያው ምክንያቱን ይነግራል።",
  "training.lessons.owner-move-stock.title": "ዕቃን በራስዎ ሱቆች መካከል ማንቀሳቀስ (Business እቅድ)",
  "plansLib.feature.pricing": "የማጽዳት እና የሮልባክ ዋጋ",
  "plansLib.includes.pricing": "የማጽዳት እና የሮልባክ ሽያጭ ዋጋ",
  "pricing.businessOnly": "የማጽዳት እና የሮልባክ ዋጋ የ Business እቅድ አካል ነው።",
