  "pricing.rollbackBadge": "ሮልባክ",
  "pricing.rollbackHint": "ሽያጩ በሚካሄድበት ጊዜ መደበኛ ዋጋው ይጠበቃል እና ከሮልባክ ዋጋው አጠገብ ይታያል። የማብቂያ ቀኑ ሲያልፍ ዋጋው በራሱ ወደ መደበኛው ይመለሳል።",
  "pricing.rollbackStarts": "ሮልባክ የሚጀምረው በ {date} ነው",
  "pricing.salePriceLabel": "የሮልባክ ዋጋ",
  "pricing.sectionTitle": "የሽያጭ ዋጋ",
  "pricing.startLabel": "ይጀምራል",
  "training.lessons.mgr-pricing.step1": "በ Business ላይ የምርት ቅጹ የሽያጭ ዋጋ ክፍል አለው። ማጽዳት ቋሚ ቅናሽ ነው — ያዘጋጁት እና ይቆያል። ሮልባክ ቀናት ያሉት ሽያጭ ነው: የሮልባክ ዋጋውን፣ የሚጀምርበትን ቀን እና የሚያልቅበትን ቀን ያዘጋጁ።",
  "training.lessons.mgr-pricing.step2": "መደበኛ ዋጋውን እንደገና መጻፍ በፍጹም አያስፈልግም: በምርቱ ላይ ይቆያል እና በምርት ዝርዝር እና በስካነር ውስጥ ከሽያጭ ዋጋው አጠገብ ይታያል፣ ስለዚህ ማንም ሰው እቃው አብዛኛውን ጊዜ ስንት እንደሚከፍል ማየት ይችላል።",
  "training.lessons.mgr-pricing.step3": "ሮልባክ ሲጀምር አዳዲስ የዋጋ መለያዎችን ያትሙ — መለያዎቹ ደንበኛው በዚያ ቀን የሚከፍለውን ዋጋ ያትማሉ። የማብቂያ ቀኑ ሲያልፍ ዋጋው በራሱ ወደ መደበኛው ይመለሳል፤ መደርደሪያውን ሲያድሱ መደበኛ መለያዎችን እንደገና ያትሙ።",
  "training.lessons.mgr-pricing.step4": "የሽያጭ ዋጋ ክፍሉ ተቆልፎ ከታየ፣ ንግዱ በ Business እቅድ ላይ አይደለም — የሽያጭ ዋጋ የዚያ እቅድ ነው፣ እና እቅዶችን የሚቀይረው ባለቤቱ ነው።",
  "training.lessons.mgr-pricing.title": "ሽያጭ ማካሄድ: ማጽዳቶች እና ሮልባኮች",
  "training.lessons.owner-pricing.step1": "በምርቱ ቅጽ ውስጥ፣ በሽያጭ ዋጋ ስር፣ ሁለት አይነት ቅናሾች አሉ። ማጽዳት ቋሚ ነው: የማጽዳት ዋጋን ያዘጋጁ እና እስኪቀይሩት ድረስ ዝቅ ብሎ ይቆያል። ሮልባክ ጊዜያዊ ሽያጭ ነው — የመጀመሪያ እና የማብቂያ ቀን ያለው ዝቅ ያለ ዋጋ፣ ከትላልቅ ሱቆች አስቀድመው እንደሚያውቁት ሽያጭ አይነት።",
  "training.lessons.owner-pricing.step2": "መደበኛ ዋጋው በፍጹም አይጠፋም። ሮልባክ በሚካሄድበት ጊዜ መተግበሪያው የሽያጭ ዋጋውን ከመደበኛ ዋጋው አጠገብ ያሳያል፣ እና የታተሙት መለያዎች የሽያጭ ዋጋውን ይይዛሉ፣ ስለዚህ መደርደሪያው ከገንዘብ መቀበያው ጋር ይጣጣማል።",
  "training.lessons.owner-pricing.step3": "የማብቂያ ቀኑ ሲያልፍ ዋጋው በራሱ ወደ መደበኛው ይመለሳል — የሚታወስ ምንም ነገር የለም፣ የሚመለስ ምንም ነገር የለም። ገና ያልጀመረ ሮልባክ የመጀመሪያ ቀኑን በምርት ዝርዝሩ ላይ በቀጥታ ይነግራል።",
  "training.lessons.owner-pricing.step4": "የሽያጭ ዋጋ የ Business እቅድ ባህሪ ነው። በ Essentials ላይ መስኮቹ ተቆልፈው ይቆያሉ፣ እና ንግድ ወደ Essentials ወርዶ ቢመለስ፣ የማጽዳት እና የሮልባክ ቅንብሮቹ በትክክል እንደተተዉበት ይቆያሉ።",
  "training.lessons.owner-pricing.title": "የማጽዳት እና የሮልባክ ዋጋ (Business እቅድ)",
  "plansLib.includes.shippingLabels": "4×6 የመላኪያ መለያዎች ለደንበኛ ትዕዛዞች — ወይም የአጓጓዥዎን መለያ በፋይል ያስቀምጡ",
  "plansLib.includes.docStyle": "በራስዎ ዘይቤ ሰነዶች — አርማ፣ ቀለም፣ ቅርጸ-ፊደል፣ ክፈፍ እና ስዕሎች",
  'plansLib.includes.taxRate': 'የግብር ተመንዎ፣ አንድ ጊዜ ይዋቀራል — አዳዲስ ትዕዛዞች ግብራቸውን ራሳቸው ይሞላሉ',
  "plansLib.includes.taxAuto": "በደንበኛዎ ግዛት መሰረት ራስ-ሰር ግብር (የአሜሪካ ግዛቶች መሰረታዊ ተመኖች)",
  "plansLib.includes.listPrices": "የእያንዳንዱ ምርት ዋጋ ከቁጥሩ ጎን",
  'plansLib.includes.codeGenerator': "የኮድ ጀነሬተር — ለራስዎ ምርቶች አዲስ የUPC፣ SKU፣ ባርኮድ እና QR ኮዶች",
  'plansLib.includes.gs1Codes': "ከራስዎ የGS1 ቅድመ-ቁጥር እውነተኛ የችርቻሮ UPC እና EAN ኮዶች",
  "plansLib.includes.bulkEdit": "በጅምላ አርትዕ እና በጅምላ ሰርዝ — ብዙ ምርቶችን በአንድ ጊዜ አዘምን ወይም አስወግድ",
