  "print.templateShippingHint": "የገዢው ስምና አድራሻ ያለው 4×6 መለያ",
  "print.shipFrom": "ከ",
  "print.recipientNameLabel": "የተቀባዩ ስም",
  "print.recipientAddressLabel": "የተቀባዩ አድራሻ",
