  "print.shippingNote": "ትዕዛዙ የመላኪያ አድራሻ ካለው፣ ከትዕዛዙ ይሞላል። እዚህ የሚተይቡት አንድ ጊዜ ይታተማል እና በጭራሽ አይቀመጥም።",
