  "print.carrier.desc": "ፖስታውን ዛሬ እንደሚገዙት ከአጓጓዡ ይግዙ — ይህ መተግበሪያ ፖስታ ፈጽሞ አይሸጥም፣ ስለዚህ የሚከፍሉት ዋጋ ሁልጊዜ የአጓጓዡ ራሱ ነው። የመለያውን ፋይል እዚህ ያስቀምጡ እና በዚህ ትዕዛዝ ላይ ለዘላለም ይቆያል፦ መዝገብዎ፣ አንድ ነገር ቢከሰት በእጅዎ ይገኛል።",
