  "print.carrier.pickOrderFirst": "ከላይ ትዕዛዝ ይምረጡ፣ ከዚያ የአጓጓዥ መለያውን እዚህ ያስቀምጡ።",
  'print.carrier.pickFirstTap': "በመጀመሪያ ከላይ አንድ ትዕዛዝ ይምረጡ — ከዚያ ይህ አዝራር የካሪየር መለያውን ወደዚያ ትዕዛዝ ያስቀምጣል።",
  "print.style.title": "የሰነድ ዘይቤ",
  "print.style.desc": "ሰነዶችዎን የእርስዎ ያድርጉ። እነዚህ ምርጫዎች ደረሰኝዎን፣ ደረሰኝ-ትንሽዎን፣ የማሸጊያ ወረቀትዎን፣ የመመለሻ ሰነዶችዎን፣ የምርት ወረቀቶችዎን፣ የቆጣሪ ወረቀቶችዎን እና የመልቀሚያ ዝርዝሮችዎን ያልብሳሉ — እና ለንግድዎ ይታወሳሉ።",
