  "print.style.previewText": "ፈጣኑ ቡናማ ቀበሮ ሰነፍ ውሻውን ይዘላል። 1234567890",
  "training.lessons.owner-shipping-labels.step1": "የህትመት ማዕከሉ በሁለቱም እቅዶች የመላኪያ መለያ ቅጥ አለው፦ የደንበኛ ትዕዛዝ ይምረጡና የገዢውን ስምና አድራሻ እና ንግድዎን በላኪነት የያዘ 4×6 መለያ ያትሙ።",
  "training.lessons.owner-shipping-labels.step2": "መለያው እንደ እያንዳንዱ የደንበኛ ሰነድ ነጭ-መለያ ነው፦ የንግድዎን ስም ብቻ ይይዛል — የዚህን መተግበሪያ ስም በፍጹም አይደለም — ስለዚህ ከሱቅዎ የመጣ እሽግ ከሱቅዎ የመጣ እንዲመስል።",
  "training.lessons.owner-shipping-labels.step3": "የደንበኛው አድራሻ ከመጨረሻ ትዕዛዛቸው በኋላ ለ90 ቀናት ከትዕዛዞቻቸው ጋር ይቀመጣል፣ እና መለያው ትዕዛዙ የተቀመጠ አድራሻ ካለው ከዚያ ይጀምራል፤ ለአንድ ጊዜ መለያ በህትመት ጊዜ የተተየበ አድራሻ እንደገና አይቀመጥም። ስሙ አሁንም ከትዕዛዙ ይሞላል ስለዚህ መለያው ከሰነዶቹ ጋር ይዛመዳል።",
  "training.lessons.owner-shipping-labels.step4": "መለያው እንደ እያንዳንዱ መለያ በተመሳሳይ አራት ግንኙነቶች ይታተማል — ብሉቱዝ፣ ዋይ-ፋይ፣ ኤተርኔት እና USB — እና 4×6 የሙቀት አታሚ መደበኛ መጠኑ ነው።",
  "training.lessons.owner-shipping-labels.step5": "ፖስታውን ከአጓጓዡ ገዝተዋል? በዚህ ክፍል ውስጥ የአጓጓዡን የመለያ ፋይል — PDF፣ PNG ወይም JPG — መስቀል ይችላሉ እና በትዕዛዙ ላይ ለዘላለም ይቆያል፦ መዝገብዎ፣ አንድ ነገር ቢከሰት በእጅዎ ይገኛል። በእውነተኛው 4×6 መጠኑ ይታተማል። መተግበሪያው ፖስታ ፈጽሞ አይሸጥም፣ ስለዚህ የአጓጓዡ ዋጋ ብቸኛው ዋጋ ነው — እና ሁልጊዜ ትክክለኛው ነው።",
  "training.lessons.owner-shipping-labels.title": "ለደንበኛ ትዕዛዞች የመላኪያ መለያዎች",
  "training.lessons.print-shipping-label.step1": "ትዕዛዝ ለመላክ ዝግጁ ሲሆን የህትመት ማዕከሉን ይክፈቱ፣ የመላኪያ መለያ ቅጥን ይምረጡ፣ ከዚያም የደንበኛውን ትዕዛዝ ይምረጡ። የገዢው ስም ከትዕዛዙ ይሞላል።",
  "training.lessons.print-shipping-label.step2": "ፓርሴሉ የሚሄድበትን አድራሻ ይፈትሹ። ትዕዛዙ የደንበኛውን አድራሻ ሲይዝ — ከመጨረሻ ትዕዛዛቸው በኋላ ለ90 ቀናት ይቀመጣል — ለእርስዎ ይሞላል፤ በህትመት ጊዜ የሚተይቡት አድራሻ እንደገና አይቀመጥም፣ ስለዚህ ከማተምዎ በፊት የፖስታ ኮዱን እና የመጨረሻውን መስመር በጥንቃቄ ይፈትሹ።",
  "training.lessons.print-shipping-label.step3": "የንግድዎ ስም በላኪነት ከላይ ይታተማል። አድራሻዎም በመለያው ላይ እንዲሆን ከፈለጉ በላኪ አድራሻ ሳጥኑ ውስጥ ይጻፉት፤ እንዲታይ ካልፈለጉ ባዶ ይተዉት።",
  "training.lessons.print-shipping-label.step4": "በ4×6 መለያ ላይ ያትሙ — የሙቀት መለያ አታሚ የተለመደ ምርጫ ነው — ወይም በማንኛውም አታሚ በአሳሹ የህትመት ቁልፍ። መለያውን ጠርዝ ላይ ሳይታጠፍ በእሽጉ ላይ ጠፍጥፎ ይለጥፉ።",
  "training.lessons.print-shipping-label.step5": "ፖስታው ከአጓጓዡ ከተገዛ፣ ይልቁንስ የመለያ ፋይሉን በትዕዛዙ ላይ ያስቀምጡ፦ አጓጓዡ የሰጠዎትን PDF፣ PNG ወይም JPG በአጓጓዡ መለያዎ ክፍል ውስጥ ይስቀሉ። እንደ መዝገብዎ በትዕዛዙ ላይ ይቆያል እና በእውነተኛው 4×6 መጠኑ ይታተማል — እና የመተግበሪያው የራሱ አድራሻ መለያ ሁልጊዜ እዚያ አለ፣ እሱን መጠቀም ሲፈልጉ።",
  "training.lessons.print-shipping-label.title": "የመላኪያ መለያ ያትሙ",
  "pos.provider.clover": "Clover",
  "pos.provider.toast": "Toast",
  "pos.provider.lightspeed": "Lightspeed",
  "pos.provider.zettle": "PayPal Zettle",
