  "staff.memberDialog.settingsAccessHint": "ምልክት የተደረገባቸው ክፍሎች በዚህ ሰው የራሱ ቅንብሮች ውስጥ ይታያሉ፣ እዚያም ማየት እና መቀየር ይችላል። ምልክት ያልተደረገባቸው ክፍሎች ተደብቀው ይቆያሉ። ምዝገባ እና ክፍያ እዚህ ፈጽሞ የሉም — እነሱ የባለቤቱ ብቻ ናቸው።",
  "staff.memberDialog.editNameHint": "ለሥራ አስኪያጆች ብቻ — ይህ ምልክት ለሠራተኞች ምንም አያደርግም።",
  "login.staffWindowClosed": "መተግበሪያው ከታቀደው ሺፍትዎ ከ10 ደቂቃ በፊት ይከፈታል፣ እና ገና የሺፍትዎ ጊዜ አልደረሰም። እባክዎ ሺፍትዎ ከመጀመሩ ትንሽ በፊት ይመለሱ።",
  "login.staffWindowClosedNext": "መተግበሪያው ከታቀደው ሺፍትዎ ከ10 ደቂቃ በፊት ይከፈታል። ቀጣዩ ሺፍትዎ {when} ይጀምራል — እባክዎ ከዚያ ትንሽ በፊት ይመለሱ።",
  "apiErrors.code.staffOutsideWindow": "መተግበሪያው ከታቀደው ሺፍትዎ ከ10 ደቂቃ በፊት ይከፈታል፣ እና ገና የሺፍትዎ ጊዜ አልደረሰም።",
  "apiErrors.graceReadOnly": "ይህ የሥራ ቦታ ለማንበብ-ብቻ ነው፡ ምዝገባው አልቋል እና የ15-ቀን የችሮታ ጊዜ ምርቶችን ለማየት ብቻ ይፈቅዳል። ምንም ለውጦች፣ ስካን፣ አስመጪ ወይም አስወጪ የለም።",
  "apiErrors.subscriptionRequired": "ይህ የሥራ ቦታ ንቁ ምዝገባ የለውም። ለመጠቀም እቅድ ይመዝገቡ — መዳረሻ የሚጀምረው ሙከራው ወይም ክፍያው ሲረጋገጥ ብቻ ነው።",
  "apiErrors.neutralStop": "ለውጦች አሁን ጠፍተዋል። በዚህ ጊዜ ምንም መጨመር ወይም መቀየር አይቻልም — የሆነ ነገር ከፈልጉ የንግዱን ባለቤት ይጠይቁ።",
  "apiErrors.welcomeScriptTooLong": "ያ የእንኳን ደህና መጣህ መልእክት በጣም ረጅም ነው።",
  "access.neutralStop.title": "ለውጦች አሁን ጠፍተዋል",
  "access.neutralStop.body": "በዚህ ጊዜ ምንም መጨመር ወይም መቀየር አይቻልም። የሆነ ነገር መቀየር ካስፈለገዎት የንግዱን ባለቤት ይጠይቁ።",
  "workforce.autoLogoutNote": "ጊዜዎችዎን ለመፈተሽ 10 ደቂቃ ያህል አለዎት — ከዚያም መተግበሪያው እስከሚቀጥለው የታቀደ ሺፍትዎ ድረስ ያስወጣዎታል።",
  "settings.install.title": "መተግበሪያውን አውርድ",
  "settings.install.description": "Luminous StockHaven ን በዚህ መሣሪያ ላይ ያግኙ — ወይም ከጠፋ ይመልሱት። በቀጥታ ከዚህ ድህረ ገጽ ይጫናል (የመተግበሪያ መደብር አያስፈልግም) እና ከዋና ማያ ገጽዎ ሙሉ ማያ ሆኖ ይከፈታል።",
  "settings.install.button": "መተግበሪያውን አውርድ",
  "settings.install.installed": "መተግበሪያው አስቀድሞ በዚህ መሣሪያ ላይ አለ — አሁን የተጫነውን መተግበሪያ እየተጠቀሙ ነው።",
  "settings.install.manualIntro": "አሁን ምንም የመጫኛ ጥያቄ የለም። አሁንም መተግበሪያውን በእጅ ማከል ይችላሉ፡",
  "settings.install.iosSteps": "በ Safari ውስጥ፣ የአጋራ አዝራሩን ይንኩ፣ ከዚያ “ወደ ዋና ማያ ገጽ አክል” ይንኩ፣ ከዚያ አክል። መተግበሪያው እንደ ማንኛውም ሌላ መተግበሪያ በዋና ማያ ገጽዎ ላይ ይሆናል።",
  "settings.install.androidSteps": "በአሳሽዎ ውስጥ፣ ምናሌውን (ሦስት ነጥቦች) ይንኩ፣ ከዚያ “መተግበሪያ ጫን” ወይም “ወደ ዋና ማያ ገጽ አክል” ይንኩ፣ እና ያረጋግጡ። መተግበሪያው እንደ ማንኛውም ሌላ መተግበሪያ በዋና ማያ ገጽዎ ላይ ይሆናል።",
  "settings.install.desktopSteps": "በአሳሽዎ የአድራሻ አሞሌ ውስጥ፣ የመጫኛ አዶ ከታየ ጠቅ ያድርጉ። አዶ ከሌለ፣ የአሳሹን ምናሌ ይክፈቱ እና “Luminous StockHaven ጫን” ወይም “ወደ ዴስክቶፕ አክል” ይምረጡ።",
  "staffWelcome.title": "ወደ Luminous StockHaven እንኳን ደህና መጡ",
