  "apiErrors.invalidValue.recordingNotPrepared": "ያ ቅጂ ሊዘጋጅ አልቻለም — እባክዎ እንደገና ይቅረጹት።",
  "training.lessons.messages-private.step5": "የድምጽ ማስታወሻም መላክ ይችላሉ፦ ከመልእክት ሳጥኑ አጠገብ ያለውን ማይክሮፎን ይንኩ፣ ይናገሩ እና አቁም ይንኩ። መጀመሪያ ያዳምጡት — ከዚያ ይላኩት፣ ወይም ይሰርዙት እና እንደገና ይቅረጹት። አንድ ሰው ሲልክልዎ፣ እውነተኛ ድምጻቸውን ለመስማት አጫውት ይንኩ።",
  "training.lessons.owner-messages-oversight.step5": "የንባብ ምልክቶች፦ የቡድን አባል እርስዎ የላኩለትን መልእክት ሲያነብ፣ እንደ ተነብቦ ምልክት ተደርጎበት ያዩታል። ሠራተኞች እና አስተዳዳሪዎች እርስ በእርስ የንባብ ምልክቶችን በተመሳሳይ መንገድ፣ በሁለቱም አቅጣጫዎች ያያሉ።",
  "training.lessons.owner-messages-oversight.step6": "የራስዎ ንባብ የማይታይ ነው። ሠራተኛ የላከልዎን መልእክት ሲያነቡ፣ እሱ የንባብ ምልክት በጭራሽ አያይም — እና ውይይቶቻቸው በመተግበሪያው ውስጥ እንደሚቀመጡ እና እርስዎ፣ ባለቤቱ፣ ሊያነቡዋቸው እንደሚችሉ ለቡድንዎ መንገር አያስፈልግዎትም። ያ ክትትል ሱቅዎን የመንከባከብ አካል ነው።",
  "training.lessons.owner-messages-oversight.step7": "በሠራተኞች መካከል ስላሉ አሉታዊ መልእክቶች ምን ማድረግ እንዳለብዎ በእርስዎ ላይ ነው። ይለፍ፣ ከአንድ ሰው ጋር በጸጥታ ይነጋገሩ፣ ወይም እርምጃ ይውሰዱ — ምርጫው የእርስዎ ነው፣ እና የት እንዳዩት በጭራሽ መንገር አያስፈልግዎትም።",
  "staffLib.perm.returnsComplete": "ተመላሽ ገንዘቦችን እና ልውጦችን ማጠናቀቅ",
