  "apiErrors.policyTextTooLong": "ያ ሰነድ እዚህ ለመተየብ በጣም ረጅም ነው። በምትኩ እንደ ፋይል ሊስቀሉት ይችላሉ።",
  "training.lessons.owner-store-policies.title": "የሱቅዎ ፖሊሲዎች እና ውሎች",
  "training.lessons.owner-store-policies.step1": "ቅንብሮችን ይክፈቱ እና የሱቅ ፖሊሲዎች እና ውሎች ካርዱን ይፈልጉ። ሁለት ሰነዶችን ይይዛል: የሱቅዎ ፖሊሲዎች — ለሱቅዎ የቤት ደንቦች — እና ውሎችዎ እና ሁኔታዎችዎ።",
  "training.lessons.owner-store-policies.step2": "እያንዳንዱ ሰነድ እዚያው ሊተየብ ወይም እንደ ፋይል ሊሰቀል ይችላል (PDF፣ ጽሑፍ፣ Word ወይም OpenDocument፣ እስከ 2 MB)። አንዱ ወይም ሌላው ነው: ጽሑፍ ማስቀመጥ ፋይሉን ይተካል፣ ፋይል መስቀልም ጽሑፉን ይተካል። ሰነድን ማስወገድ ያጸዳዋል።",
  "training.lessons.owner-store-policies.step3": "ቡድንዎ ሁለቱንም ሰነዶች አንድ ጊዜ ያያቸዋል፣ በመጀመሪያ ጅምራቸው ላይ በእንኳን ደህና መጣህ ገጻቸው ላይ፣ እና በማንኛውም ጊዜ በቅንብሮቻቸው ውስጥ ሊያነባቸው ይችላል። ለቡድንዎ ንባብ ብቻ ናቸው — እርስዎ ብቻ ሊጽፏቸው ወይም ሊለውጧቸው ይችላሉ።",
  "training.lessons.owner-store-policies.step4": "እያንዳንዱ ንግድ የራሱን ሰነዶች ይይዛል: እዚህ የሚጽፉት የዚህ ሱቅ ብቻ ነው እና በሌላ ንግድ ውስጥ በፍጹም አይታይም። የLuminous StockHaven የራሱ ውሎች እና ፖሊሲዎች በቅንብሮች ውስጥ ከእርስዎት ጎን ይኖራሉ፣ ሁሉም ሰው እነሱንም ሊያነባቸው ይችላል።",
  "training.lessons.welcome-basics.step5": "የሱቅዎ ፖሊሲዎች እና ውሎች በእንኳን ደህና መጣህ ገጽዎ ላይ አንድ ጊዜ ይታያሉ፣ እና በቅንብሮች ውስጥ ይኖራሉ፣ እዚያም በማንኛውም ጊዜ ሊያነቡዋቸው ይችላሉ።",
  "apiErrors.policyDocNotFound": "ያ ሰነድ ከሁለቱ አንዱ አይደለም።",
  "apiErrors.policyFileNotFound": "ለያ ሰነድ ምንም ፋይል አልተቀመጠም።",
  "staffLib.perm.staffRoster": "ሙሉ የሰራተኞች ዝርዝርን ይመልከቱ",
  "staffLib.area.staffAccess": "የሰራተኞች ዝርዝር",
  "staff.memberDialog.staffAccessHint": "ለሥራ አስኪያጆች ብቻ — በዚህ ምልክት፣ ይህ ሥራ አስኪያጅ ሙሉውን የሰራተኞች ዝርዝር ማየት ይችላል፣ ለማንበብ ብቻ። ያለሱ፣ ሥራ አስኪያጅ የራሱን ካርድ ብቻ ያያል። ይህ ምልክት ለሠራተኞች ምንም አያደርግም።",
  "workforce.schedule.clear": "አጽዳ",
