  "workforce.messages.charLimit": "ይህ የአንድ መልእክት ወሰን ነው — ከዚህ በላይ አይገባም።",
  "staffLib.perm.alertsView": "የዝቅተኛ ክምችት ማስጠንቅቂያዎችን ይመልከቱ",
  "staffLib.perm.productsReorder": "የእንደገና ማዘዣ ነጥቦችን ይቀይሩ",
  "staffLib.area.lowStockAccess": "ዝቅተኛ ክምችት",
  "staff.memberDialog.lowStockAccessHint": "በመጀመሪያው ምልክት፣ ይህ ሰው የዝቅተኛ ክምችት ማስጠንቅቂያዎችን ያያል — የ«ትኩረት ያስፈልገዋል» ሳጥን፣ የዝቅተኛ ክምችት ገጽ እና የዝቅተኛ ደረጃ ምልክቶች። በሁለተኛው ምልክት፣ የምርት እንደገና ማዘዣ ነጥብ መቀየር ይችላል፤ ከሌለ፣ የእንደገና ማዘዣ ነጥብ ሳጥኑ መታየቱን ይቀጥላል፣ ነገር ግን በእሱ ላይ የሚደረግ ለውጥ አይቀመጥም።",
  "apiErrors.reorderChangeReserved": "ባለቤቱ ብቻ፣ ወይም እንደገና ማዘዣ ነጥቦችን እንዲቀይር ባለቤቱ የፈቀደለት የቡድን አባል ብቻ፣ እንደገና ማዘዣ ነጥብ መቀየር ይችላል።",
  "apiErrors.alertsViewReserved": "ባለቤቱ ብቻ፣ ወይም የዝቅተኛ ክምችት ማስጠንቅቂያዎችን እንዲያይ ባለቤቱ የፈቀደለት የቡድን አባል ብቻ፣ የዝቅተኛ ክምችት ማስጠንቅቂያዎችን ማየት ይችላል።",
  "apiErrors.quizRequired": "ይህ ትምህርት በአጭር ፈተና ይጠናቀቃል — ትምህርቱን ለማጠናቀቅ በትክክል ይመልሱት።",
  "apiErrors.trainingIncomplete": "ገና አይደለም — ይህ ሰው አሁንም ማጠናቀቅ ያለበት ሥልጠና አለው።",
