  "settings.policyQuiz.empty": "ገና ምንም ጥያቄዎች የሉም። ምንም ጥያቄ ከሌለ፣ ይህ ሥልጠና ንባቡ ብቻ ነው።",
  "settings.policyQuiz.expected": "የሚጠበቅ መልስ",
  "settings.policyQuiz.expectedHint": "በራስዎ ቃላት የሚጠብቁት መልስ። ከቃል ወደ ቃል ማለት ይቻላል የሚዛመድ መልስ ወዲያውኑ ትክክል ተብሎ ይቆጠራል፤ የተቀሩት ለእርስዎ እንዲመለከቷቸው ይመጣሉ።",
  "settings.policyQuiz.hint": "ስለዚህ ሰነድ ለቡድንዎ ጥያቄዎች ይጻፉ። አንድ ሰው በሰራተኞች መዝገቡ ውስጥ ይህን ሥልጠና ሲሰይሙለት በሥልጠና ውስጥ ይመልሳቸዋል። ምን ያህል ጥያቄዎች እንደሚጽፉ ገደብ የለም።",
  "settings.policyQuiz.mcLabel": "ብዙ ምርጫ",
