  "settings.policyQuiz.passLine": "የማለፊያ መስመር",
  "settings.policyQuiz.passLineHint": "አንድ ሰው ይህን ሥልጠና ለማጠናቀቅ የሚያስፈልገው ውጤት — የብዙ ምርጫ መልሶችን ብቻ በመቁጠር።",
