  "apiErrors.profileOwnerNameOnly": "የንግዱ ባለቤት ብቻ የባለቤቱን ስም ማዘጋጀት ይችላል።",
  "apiErrors.profilePhotosApproveOwnerOnly": "የንግዱ ባለቤት ብቻ የቡድን ፎቶዎችን ማጽደቅ ይችላል።",
  "apiErrors.profilePhotosNoneWaiting": "ያ የቡድን አባል ማጽደቅ የሚጠብቅ ፎቶ የለውም።",
  "apiErrors.profileOwnerNameTooLong": "ስምዎን በ80 ቁምፊዎች ወይም ከዚያ ባነሰ ይወስኑት።",
  "training.lessons.your-profile-photo.title": "የመገለጫ ፎቶዎ",
  "training.lessons.your-profile-photo.step1": "ባለቤቱ ካጸደቀው በኋላ ፎቶዎ ከስምዎ አጠገብ በመተግበሪያው ላይኛው ክፍል፣ በሰራተኞች ገጽ ላይ፣ እና ከመልእክቶችዎ አጠገብ ይታያል። እስከዚያ ድረስ፣ የስምዎ የመጀመሪያ ፊደላት ብቻ ይታያሉ።",
  "training.lessons.your-profile-photo.step2": "ቅንብሮችን ይክፈቱ እና የመገለጫ ፎቶዎን ይፈልጉ። የራስዎን ፎቶ ይምረጡ እና ይላኩት። ለማጽደቅ ወደ ባለቤቱ ይሄዳል — በመጠበቅ ላይ እያለ የትም አይታይም።",
  "training.lessons.your-profile-photo.step3": "ባለቤቱ ሲያጸድቀው፣ ደወልዎ ይደወላል እና ፎቶዎ መታየት ይጀምራል። ካልጸደቀ፣ የተለየ ፎቶ ይምረጡ እና በምትኩ ያንን ይላኩ።",
  "training.lessons.your-profile-photo.step4": "ፎቶዎን መቀየር በተመሳሳይ መንገድ ይሰራል፡ አዲሱ ማጽደቅ ይጠብቃል፣ አዲሱ እስኪጸደቅ ድረስ የአሁኑ ፎቶዎ በቦታው ይቆያል። ለውጡ ካልጸደቀ፣ ሌላውን ፎቶዎን ይይዛሉ።",
  "training.lessons.owner-profile-photos.title": "የመገለጫ ፎቶዎች እና ስምዎ",
  "training.lessons.owner-profile-photos.step1": "የሁሉም ሰው ፎቶ ከስማቸው አጠገብ በመተግበሪያው ላይኛው ክፍል፣ በሰራተኞች ገጽዎ ላይ፣ እና ከመልእክቶቻቸው አጠገብ ይታያል። እርስዎ እስኪያጸድቁት ድረስ የቡድን አባል ፎቶ የትም አይታይም — ማጽደቅ የእርስዎ ብቻ ነው፣ ማንም የራሱን ፎቶ ማጽደቅ አይችልም።",
  "training.lessons.owner-profile-photos.step2": "አንድ ሰው ፎቶ ሲልክ፣ ደወልዎ ይደወላል። ለማየት የሰራተኞች ገጹን ይክፈቱ፣ ከዚያ አጽድቅ ወይም አታጽድቅ ይምረጡ። ካላጸደቁት፣ ሰውየው ሌላ ፎቶ እንዲመርጥ ይነገራል።",
  "training.lessons.owner-profile-photos.step3": "አንድ ሰው ፎቶውን ከቀየረ፣ አዲሱ በተመሳሳይ መንገድ ማጽደቅዎን ይጠብቃል። በመጠበቅ ላይ እያለ የአሁኑ ፎቶው በቦታው ይቆያል — ለውጡን ካላጸደቁም ይቆያል።",
  "training.lessons.owner-profile-photos.step4": "የራስዎ ፎቶ ማጽደቅ አያስፈልገውም፡ በቅንብሮች ውስጥ፣ በመገለጫ ፎቶዎ ስር ያዘጋጁት። ተመሳሳይ ካርድ ስምዎን ይይዛል — እዚያ ያዘጋጁት ስም ቡድንዎ በሚያየው ቦታ ሁሉ፣ በመተግበሪያው እና በመልእክቶች ውስጥ፣ ባለቤት የሚለውን ቃል ይተካዋል።",
  "payroll.dd.corrected": "የተስተካከለ ቅጽ",
  "payroll.dd.correctedDone": "የተስተካከሉ ዝርዝሮችዎ ለባለቤቱ ተልከዋል።",
