  "payroll.dd.fixHelp": "አሃዝ ከተሳሳተ ዝርዝሮችዎን ያስተካክሉ እና ቅጹን እንደገና ይላኩ። አዲሱ የተፈረመበት ቅጽዎ የድሮውን ይተካዋል፣ እናም እንደተስተካከለ ለባለቤቱ ይነገራል።",
