  "apiErrors.clockGate.notScheduled": "አሁን ለመሥራት አልተያዘልዎትም፣ ለእርስዎ የተከፈተ የጥሪ መስኮትም የለም።",
  "apiErrors.clockAdmin.notGranted": "ባለቤቱ ብቻ፣ ወይም ባለቤቱ ወደ ሥራ መጥራትን እና የሰዓት እርማቶችን ያመነበት ሥራ አስኪያጅ ብቻ ያንን ማድረግ ይችላል።",
  "apiErrors.clockAdmin.ownerOnlyForManager": "የሥራ አስኪያጅን ጥሪዎች እና የጊዜ መዝገቦች ባለቤቱ ብቻ ማስተዳደር ይችላል።",
