  "apiErrors.clockFix.breakOutside": "የእረፍት ጊዜያት በመግባት እና በመውጣት ጊዜያት መካከል መሆን አለባቸው።",
  "apiErrors.clockFix.invalidTime": "እያንዳንዱን ጊዜ እንደ ትክክለኛ ቀን እና ሰዓት ይላኩ።",
  "apiErrors.notFound.timeEntryFound": "የጊዜ መዝገብ አልተገኘም።",
  "training.lessons.mgr-clock-callin.title": "ወደ ሥራ መጥራት እና የሰዓት እርማቶች",
  "training.lessons.mgr-clock-callin.step1": "ባለቤቱ ለሥራ አስኪያጅ አንድ ምልክት መስጠት ይችላል — ወደ ሥራ መጥራት እና የሰዓት እርማቶች። በእሱ፣ ለአንድ የሠራተኞች አባል የጥሪ መስኮት መክፈት እና ከሠራተኞች ገጽ የጊዜ መዝገቦችን ማረም ይችላሉ።",
  "training.lessons.mgr-clock-callin.step2": "የጥሪ መስኮት ምንም ፈረቃ በማይሸፍነው ጊዜ አንድ ሰው እንዲገባ እና እንዲገባ ያስችለዋል። ከሠራተኞች ገጽ፣ በወደ ሥራ መጥራት እና ያመለጡ መውጣቶች ካርድ ላይ ይክፈቱት።",
  "training.lessons.mgr-clock-callin.step3": "መስኮቱ ሰውዬው እስኪወጣ ድረስ ክፍት ሆኖ ይቆያል — ከዚያ በኋላ የተለመደው የ10-ደቂቃ የመውጣት ይቅርታ ይከተላል — ወይም እርስዎ ወይም ባለቤቱ ቀድመው እስኪዘጉት ድረስ። ምንም ነገር በራሱ አይዘጋውም።",
  "training.lessons.mgr-clock-callin.step4": "አንድ ሰው መውጣቱን ሲረሳ፣ የታቀደው ፈረቃ እንዳለቀ መዝገቡ በሠራተኞች ገጽ እና በደመወዝ ዝርዝር ላይ ምልክት ይደረግበታል፣ እርስዎም ባለቤቱም ይገለጽላችኋል። መዝገቡ እስኪታረም ድረስ መቁጠሩን ይቀጥላል።",
  "training.lessons.mgr-clock-callin.step5": "መዝገቡን ከሠራተኞች ገጽ ያርሙ፦ መግባትን፣ መውጣትን እና የእረፍት ጊዜያትን ያዘጋጁ። ሥራ አስኪያጅ የሠራተኞችን መዝገቦች ብቻ ያርማል — የሥራ አስኪያጅ የራሱ መዝገቦች በባለቤቱ ይታረማሉ።",
  "staffLib.perm.staffDocuments": "የሰራተኞች ሰነዶች",
  "staffLib.area.documentsAccess": "የሰራተኞች ሰነዶች",
  "staff.memberDialog.documentsAccessHint": "ለአስተዳዳሪዎች ብቻ — በዚህ ምልክት፣ ይህ አስተዳዳሪ የሰራተኛ አባላትን የሰነድ ፋይሎች መክፈት ይችላል፡ ለእያንዳንዱ ሰው የሚቀመጡ ወረቀቶች፣ እንደ W-4 ቅጾች፣ የሥራ ማመልከቻዎች እና የመታወቂያ ቅጂዎች። መጀመሪያ ማረጋገጫ ይጠየቃሉ — እነዚህ ፋይሎች የማኅበራዊ ዋስትና ቁጥሮች እና የልደት ቀናት አሏቸው። ይህ ምልክት ለሰራተኞች ምንም አያደርግም።",
  "staff.documentsWarning.body": "ይህ ሰው የማኅበራዊ ዋስትና ቁጥሮችን እና የልደት ቀናትን ጨምሮ ስለ ሰራተኛ አባላትዎ ሚስጥራዊ መረጃ ማየት ይችላል።",
  "staff.documentsWarning.confirm": "አዎ፣ ተረድቻለሁ",
  "staff.documents.title": "የሰራተኞች ሰነዶች",
  "staff.documents.desc": "ለእያንዳንዱ ሰው የሚያስቀምጡት ወረቀቶች — የ W-4 ቅጾች፣ የሥራ ማመልከቻዎች፣ የግብር ቅጾች፣ የመታወቂያ ቅጂዎች። እርስዎ ብቻ፣ እና የሰራተኞች ሰነዶች ምልክት የሚሰጡት አስተዳዳሪ ብቻ እነዚህን ፋይሎች መክፈት ይችላሉ።",
